<script setup>
import { computed, inject } from 'vue';
import V2Panel from '../components/shared/V2Panel.vue';
import V2Icon from '../components/shared/V2Icon.vue';
import EventExperienceFields from '../components/events/EventExperienceFields.vue';
import BrandedGameFields from '../components/events/BrandedGameFields.vue';
import EventQuizEditor from '../components/events/EventQuizEditor.vue';
import EventStoriesEditor from '../components/events/EventStoriesEditor.vue';

const props = defineProps({ detail: { type: String, default: '' } });
const c = inject('admin-v2');
const tabs = [{ id:'settings', label:'Esperienza', icon:'settings' }, { id:'prizes', label:'Premi', icon:'lottery' }, { id:'feedback', label:'Sondaggio', icon:'results' }, { id:'quiz', label:'Quiz', icon:'check' }, { id:'stories', label:'Stories', icon:'selfies' }];
const routeParts = computed(() => props.detail.split('/'));
const creating = computed(() => routeParts.value[0] === 'create');
const selected = computed(() => c.availableEvents.find(event => String(event.id) === routeParts.value[0]));
const tab = computed(() => tabs.some(item => item.id === routeParts.value[1]) ? routeParts.value[1] : 'settings');
const busyEvent = event => c.updatingEventId === event.id || c.concludingEventId === event.id || c.busy(`event-delete-${event.id}`);
const status = event => event.is_active ? event.votes_closed ? 'Votazioni chiuse' : 'In diretta' : 'Inattivo';
const statusClass = event => event.is_active ? event.votes_closed ? 'warning' : 'success' : '';
function confirmDelete(event) {
 c.confirmAction('Eliminare questo evento?', `Confermi l’eliminazione di “${c.eventLabel(event)}”? L’operazione rimuove l’evento dalla società.`, () => c.run(`event-delete-${event.id}`, async () => { await c.deleteEvent(event.id); }, 'Evento eliminato.'));
}
function confirmConclude(event) {
 c.confirmAction('Concludere questo evento?', `“${c.eventLabel(event)}” verrà spostato nello storico. Potrai consultarne risultati e report.`, () => c.run(`event-conclude-${event.id}`, () => c.concludeEvent(event.id), 'Evento spostato nello storico.'));
}
function deactivate() {
 c.confirmAction('Disattivare gli eventi?', 'Nessun evento della società resterà attivo per il voto.', () => c.run('events-deactivate', c.deactivateEvents, 'Eventi disattivati.'));
}
function saveSection(event, section) {
 const action = { settings:c.saveEventSettings, prizes:c.saveEventPrizes, feedback:c.saveEventFeedbackSurvey }[section];
 return c.run(`event-save-${event.id}`, () => action(event), 'Modifiche salvate.');
}
</script>

<template>
 <div class="v2-stack v2-events">
  <template v-if="!detail">
   <div class="v2-events-heading"><div><span class="v2-eyebrow">LA TUA PROGRAMMAZIONE</span><h2>Prepara la prossima esperienza</h2><p class="v2-muted">Organizza le partite e gestisci tutto ciò che i tifosi vivono in arena.</p></div><button class="v2-button v2-primary" @click="c.navigate('events','create')"><V2Icon name="plus" :size="17" />Crea evento</button></div>
   <div v-if="c.activeEventEntry" class="v2-live-strip"><div><span class="v2-badge" :class="statusClass(c.activeEventEntry)">{{ status(c.activeEventEntry) }}</span><strong>{{ c.activeEventLabel }}</strong><small>{{ c.activeEventDateLabel }} · {{ c.activeEventLocation }}</small></div><div class="v2-toolbar"><button class="v2-button" @click="c.navigate('events',String(c.activeEventEntry.id))">Gestisci evento</button><button class="v2-button" @click="c.navigate('closing')">Gestisci votazioni</button></div></div>
   <V2Panel title="Eventi della società" :description="`${c.visibleEvents.length} eventi aperti nella programmazione. Gli eventi conclusi sono nello storico.`">
    <template #actions><button class="v2-button" :disabled="c.busy('events-refresh')" @click="c.run('events-refresh', c.loadEvents)"><V2Icon name="refresh" :size="16" />Aggiorna</button></template>
    <div class="v2-events-filters"><label class="v2-field">Cerca evento<input v-model="c.eventSearch" type="search" placeholder="Squadra o luogo…" /></label><label class="v2-field">Stato<select v-model="c.eventStatusFilter"><option value="all">Tutti gli stati</option><option value="active">Attivi</option><option value="inactive">Inattivi</option><option value="closed">Votazioni chiuse</option></select></label><button v-if="c.eventSearch || c.eventStatusFilter !== 'all'" class="v2-button" @click="c.eventSearch=''; c.eventStatusFilter='all'">Azzera filtri</button></div>
    <div v-if="c.filteredVisibleEvents.length" class="v2-event-list"><article v-for="event in c.filteredVisibleEvents" :key="event.id" class="v2-event-row"><div class="v2-event-date"><V2Icon name="events" :size="22" /><small>#{{ event.id }}</small></div><div class="v2-event-identity"><button class="v2-event-title" @click="c.navigate('events',String(event.id))">{{ c.eventLabel(event) }}</button><p>{{ c.formatEventDate(event.start_datetime) }}<template v-if="event.location"> · {{ event.location }}</template></p><span class="v2-badge" :class="statusClass(event)">{{ status(event) }}</span></div><div class="v2-toolbar v2-event-list-actions"><button class="v2-button" @click="c.navigate('events',String(event.id))">Configura<V2Icon name="arrow-right" :size="16" /></button><button class="v2-button" :disabled="event.is_active || busyEvent(event)" @click="c.run(`event-activate-${event.id}`,()=>c.activateEvent(event.id),'Evento attivato.')">{{ event.is_active ? 'Attivo' : c.updatingEventId === event.id ? 'Attivazione…' : 'Attiva' }}</button></div></article></div>
    <div v-else class="v2-empty"><V2Icon name="events" :size="32" /><p>{{ c.visibleEvents.length ? 'Nessun evento corrisponde ai filtri.' : 'La prossima partita parte da qui.' }}</p><button v-if="!c.visibleEvents.length" class="v2-button v2-primary" @click="c.navigate('events','create')">Crea il primo evento</button></div>
    <div class="v2-toolbar v2-events-footer"><button class="v2-button" @click="c.navigate('history')">Apri storico e report</button><button class="v2-button" :disabled="!c.activeEventId || c.isDisablingEvents" @click="deactivate">{{ c.isDisablingEvents ? 'Disattivazione…' : 'Disattiva tutti gli eventi' }}</button></div>
   </V2Panel>
  </template>

  <template v-else-if="creating">
   <div class="v2-toolbar"><button class="v2-button" @click="c.navigate('events')"><V2Icon name="chevron-left" :size="16" />Tutti gli eventi</button><span class="v2-badge">Nuovo evento</span></div>
   <p v-if="!c.hasEnoughTeams" class="v2-notice">Per creare un evento aggiungi almeno due squadre.<button class="v2-link" @click="c.navigate('teams')">Gestisci squadre</button></p>
   <form class="v2-stack" @submit.prevent="c.run('event-create',c.createEvent,'Evento creato.')">
    <V2Panel title="Dettagli della partita" description="Scegli le squadre e indica quando e dove si gioca."><fieldset :disabled="!c.hasEnoughTeams || c.busy('event-create')" class="v2-event-plain-fieldset"><div class="v2-grid-2"><label class="v2-field">Squadra di casa *<select v-model.number="c.newEvent.team1_id" required><option :value="0" disabled>Seleziona la squadra di casa</option><option v-for="team in c.teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label class="v2-field">Squadra ospite *<select v-model.number="c.newEvent.team2_id" required><option :value="0" disabled>Seleziona la squadra ospite</option><option v-for="team in c.teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label class="v2-field">Data e ora *<input v-model="c.newEvent.start_datetime" type="datetime-local" required /></label><label class="v2-field">Luogo<input v-model.trim="c.newEvent.location" placeholder="Es. Palazzetto dello Sport" /></label></div></fieldset></V2Panel>
    <V2Panel title="Esperienza dei tifosi" description="Le esperienze abilitate saranno disponibili nella pagina di voto."><EventExperienceFields :draft="c.newEvent" :disabled="!c.hasEnoughTeams || c.busy('event-create')" /></V2Panel>
    <V2Panel title="Sponsor e interazione"><BrandedGameFields :draft="c.newEvent" :disabled="!c.hasEnoughTeams || c.busy('event-create')" /></V2Panel>
    <V2Panel title="Premi della partita" description="Aggiungi i premi e il testo del messaggio per i vincitori. I premi senza nome non saranno creati."><div class="v2-stack"><fieldset v-for="(prize,index) in c.newEventPrizes" :key="index" :disabled="!c.hasEnoughTeams || c.busy('event-create')" class="v2-stack"><legend>Premio {{ index + 1 }}</legend><div class="v2-grid-2"><label class="v2-field">Nome del premio<input v-model.trim="prize.name" :placeholder="`Premio ${index + 1}`" /></label><label class="v2-field">Testo SMS vittoria<input v-model.trim="prize.winSmsText" placeholder="Messaggio per il vincitore" /></label></div><div><button class="v2-button v2-danger" type="button" :disabled="c.newEventPrizes.length <= 1" @click="c.removeNewEventPrize(index)">Rimuovi premio {{ index + 1 }}</button></div></fieldset><div><button class="v2-button" type="button" :disabled="!c.hasEnoughTeams || c.busy('event-create')" @click="c.addNewEventPrize">Aggiungi premio</button></div></div></V2Panel>
    <V2Panel><p v-if="c.lastCreatedEventLink" class="v2-success" role="status">Evento creato. <a :href="c.lastCreatedEventLink" target="_blank" rel="noopener">Apri pagina voto</a><button class="v2-link" type="button" @click="c.run('copy-event-link',()=>c.copyLink(c.lastCreatedEventLink))">Copia link</button></p><div class="v2-toolbar"><button class="v2-button v2-primary" :disabled="!c.hasEnoughTeams || c.busy('event-create')">{{ c.busy('event-create') ? 'Creazione in corso…' : 'Crea evento' }}</button><button class="v2-button" type="button" @click="c.navigate('events')">Torna all’elenco</button></div></V2Panel>
   </form>
  </template>

  <template v-else-if="selected">
   <div class="v2-toolbar"><button class="v2-button" @click="c.navigate('events')"><V2Icon name="chevron-left" :size="16" />Tutti gli eventi</button><span class="v2-badge" :class="statusClass(selected)">{{ status(selected) }}</span></div>
   <V2Panel :title="c.eventLabel(selected)" :description="`${c.formatEventDate(selected.start_datetime)}${selected.location ? ` · ${selected.location}` : ''}`"><div class="v2-toolbar"><button class="v2-button v2-primary" :disabled="selected.is_active || busyEvent(selected)" @click="c.run(`event-activate-${selected.id}`,()=>c.activateEvent(selected.id),'Evento attivato.')">{{ selected.is_active ? 'Evento attivo' : c.updatingEventId === selected.id ? 'Attivazione…' : 'Attiva evento' }}</button><button class="v2-button" @click="c.openVote(selected.id)"><V2Icon name="arrow-up-right" :size="16" />Pagina voto</button><button class="v2-button" @click="c.run('copy-event-link',()=>c.copyLink(c.buildEventLink(selected.id)))">Copia link</button><button class="v2-button" :disabled="busyEvent(selected)" @click="confirmConclude(selected)">{{ c.concludingEventId === selected.id ? 'Conclusione…' : 'Concludi evento' }}</button><button class="v2-button v2-danger" :disabled="busyEvent(selected)" @click="confirmDelete(selected)">Elimina evento</button></div><code class="v2-event-url">{{ c.buildEventLink(selected.id) }}</code></V2Panel>
   <V2Panel>
    <nav class="v2-tabs" aria-label="Configurazione evento"><button v-for="item in tabs" :key="item.id" type="button" :aria-current="tab === item.id ? 'page' : undefined" @click="c.navigate('events',`${selected.id}/${item.id}`)"><V2Icon :name="item.icon" :size="16" />{{ item.label }}</button></nav>
    <form v-if="tab === 'settings'" class="v2-stack" @submit.prevent="saveSection(selected,'settings')"><h2>Configura l’esperienza in arena</h2><EventExperienceFields :draft="selected" :disabled="c.isSavingPrizesFor(selected.id)" /><BrandedGameFields :draft="selected" :disabled="c.isSavingPrizesFor(selected.id)" /><p v-if="c.eventSettingsErrors[selected.id]" class="v2-error" role="alert">{{ c.eventSettingsErrors[selected.id] }}</p><div><button class="v2-button v2-primary" :disabled="c.isSavingPrizesFor(selected.id) || c.busy(`event-save-${selected.id}`)">{{ c.isSavingPrizesFor(selected.id) ? 'Salvataggio…' : 'Salva esperienza' }}</button></div></form>
    <form v-else-if="tab === 'prizes'" class="v2-stack" @submit.prevent="saveSection(selected,'prizes')"><div><h2>Premi e vincitori</h2><p class="v2-muted">I premi già assegnati non possono essere rimossi. Per annullare un’assegnazione apri la lotteria.</p></div><fieldset v-for="(prize,index) in c.prizeDraftsFor(selected.id)" :key="prize.id || index" class="v2-stack" :disabled="c.isSavingPrizesFor(selected.id)"><legend>Premio {{ index + 1 }}</legend><div class="v2-grid-2"><label class="v2-field">Nome premio<input v-model="prize.name" :placeholder="`Premio ${index + 1}`" /></label><label class="v2-field">Testo SMS vittoria<input v-model="prize.winSmsText" placeholder="Messaggio per il vincitore" /></label></div><p v-if="prize.winner" class="v2-notice">Vincitore: {{ c.prizeWinnerLabel(prize) }}</p><div><button class="v2-button v2-danger" type="button" :disabled="!!prize.winner || c.prizeDraftsFor(selected.id).length <= 1" @click="c.removePrizeDraft(selected.id,index)">Rimuovi premio {{ index + 1 }}</button></div></fieldset><p v-if="c.eventPrizeErrors[selected.id]" class="v2-error" role="alert">{{ c.eventPrizeErrors[selected.id] }}</p><div class="v2-toolbar"><button class="v2-button" type="button" :disabled="c.isSavingPrizesFor(selected.id)" @click="c.addPrizeDraft(selected.id)">Aggiungi premio</button><button class="v2-button v2-primary" :disabled="c.isSavingPrizesFor(selected.id) || c.busy(`event-save-${selected.id}`)">{{ c.isSavingPrizesFor(selected.id) ? 'Salvataggio…' : 'Salva premi' }}</button><button class="v2-button" type="button" @click="c.goToLottery">Apri lotteria</button></div></form>
    <form v-else-if="tab === 'feedback'" class="v2-stack" @submit.prevent="saveSection(selected,'feedback')"><div><h2>Sondaggio dei tifosi</h2><p class="v2-muted">Personalizza le domande e le risposte del sondaggio per i tuoi tifosi.</p></div><fieldset v-for="(question,index) in c.feedbackDraftFor(selected.id).questions" :key="question.id" class="v2-stack" :disabled="c.isSavingPrizesFor(selected.id)"><legend>Domanda {{ index + 1 }}</legend><label class="v2-field">Testo della domanda<input v-model="question.title" :placeholder="question.id" /></label><div class="v2-grid-2"><label v-for="answer in question.answers" :key="answer.value" class="v2-field"><span>{{ answer.icon }} Etichetta risposta · {{ answer.value }}</span><input v-model="answer.label" :placeholder="answer.value" /></label></div></fieldset><label class="v2-field">Domanda per i suggerimenti (facoltativa)<textarea v-model="c.feedbackDraftFor(selected.id).suggestionPrompt" maxlength="120" rows="3" :disabled="c.isSavingPrizesFor(selected.id)" placeholder="Chiedi ai tifosi cosa migliorare…"></textarea><small>Massimo 120 caratteri.</small></label><p v-if="c.eventFeedbackErrors[selected.id]" class="v2-error" role="alert">{{ c.eventFeedbackErrors[selected.id] }}</p><div><button class="v2-button v2-primary" :disabled="c.isSavingPrizesFor(selected.id) || c.busy(`event-save-${selected.id}`)">{{ c.isSavingPrizesFor(selected.id) ? 'Salvataggio…' : 'Salva sondaggio' }}</button></div></form>
    <EventQuizEditor v-else-if="tab === 'quiz'" :event="selected" />
    <EventStoriesEditor v-else-if="tab === 'stories'" :event="selected" />
   </V2Panel>
  </template>
  <V2Panel v-else title="Evento non disponibile"><p class="v2-muted">L’evento richiesto non è nella programmazione della società. Se è stato concluso, cercalo nello storico.</p><div class="v2-toolbar v2-events-footer"><button class="v2-button" @click="c.navigate('events')">Tutti gli eventi</button><button class="v2-button" @click="c.navigate('history')">Apri storico</button></div></V2Panel>
 </div>
</template>

<style scoped>
.v2-events-heading{display:flex;align-items:center;justify-content:space-between;gap:24px}.v2-events-heading h2{font-size:23px;margin:9px 0!important;letter-spacing:-.7px}.v2-events-heading p{font-size:13px}.v2-live-strip{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px;border:1px solid #bdd8ca;border-radius:12px;background:#edf6f0}.v2-live-strip>div:first-child{display:grid;gap:8px;min-width:0}.v2-live-strip .v2-badge{justify-self:start}.v2-live-strip strong{font-size:17px;overflow-wrap:anywhere}.v2-events-filters{display:flex;align-items:end;gap:16px;flex-wrap:wrap;margin-bottom:24px}.v2-events-filters>.v2-field:first-child{flex:1;min-width:min(240px,100%)}.v2-events-filters>.v2-field:nth-child(2){width:200px}.v2-event-list{display:grid;gap:0;border:1px solid var(--v2-line);border-radius:10px}.v2-event-row{display:flex;gap:18px;align-items:center;min-width:0;padding:22px;border-bottom:1px solid var(--v2-line)}.v2-event-row:last-child{border-bottom:0}.v2-event-date{height:60px;width:58px;display:grid;place-items:center;padding:7px;background:var(--v2-soft);border-radius:9px;color:var(--v2-muted);flex:none}.v2-event-date small{font-size:10px}.v2-event-identity{flex:1;min-width:0}.v2-event-title{display:block;color:var(--v2-ink);font-size:15px;font-weight:650;text-align:left;min-height:44px;padding:8px 0;overflow-wrap:anywhere}.v2-event-title:hover{text-decoration:underline;color:var(--v2-primary)}.v2-event-identity p{color:var(--v2-muted);font-size:12px;margin-bottom:10px!important}.v2-event-list-actions{justify-content:flex-end}.v2-events-footer{margin-top:24px;padding-top:20px;border-top:1px solid var(--v2-line)}.v2-events .v2-empty{display:grid;justify-items:center;gap:16px}.v2-event-url{display:block;color:var(--v2-muted);margin-top:18px;font-size:11px}.v2-event-plain-fieldset{padding:0!important;border:0!important}.v2-events .v2-tabs button{display:inline-flex;align-items:center;gap:8px}.v2-events .v2-success{margin-bottom:16px!important}
@media(max-width:1100px){.v2-event-row{flex-wrap:wrap}.v2-event-list-actions{margin-left:76px;justify-content:flex-start}.v2-live-strip{align-items:flex-start;flex-direction:column}}@media(max-width:640px){.v2-events-heading{align-items:flex-start;flex-direction:column;gap:16px}.v2-events-heading>.v2-button{width:100%}.v2-event-row{padding:16px;gap:12px}.v2-event-date{width:44px;height:54px}.v2-event-list-actions{margin-left:0;width:100%}.v2-event-list-actions>.v2-button{flex:1}.v2-events-filters{align-items:stretch;gap:14px}.v2-events-filters>.v2-field:nth-child(2){width:100%}.v2-live-strip{padding:18px}.v2-live-strip .v2-toolbar{width:100%}.v2-live-strip .v2-button{flex:1}.v2-events-footer>.v2-button{flex:1}}
</style>
